#pragma once
#include "kstationVoiceFeedbackTask.h"
#include "kstationNativeMidiPump.h"
#include <array>
#include <variant>
namespace kstation {
class NativeVoiceFeedback final {
 using T=VoiceFeedbackTask;using Q=DspRefreshTask;struct Job{std::variant<T,Q>task;uint32_t returned=0;};
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x819a,0x8218},{0x834a,0x8366}}};static bool candidate(uint32_t pc){return (pc>=0x819a&&pc<0x8218)||(pc>=0x834a&&pc<0x8366);}bool active()const{return depth_!=0;}void reset(){depth_=0;}
 bool step(Stage1Cpu&c){using namespace midi_projection;if(blocked(c))return false;auto at=uint32_t(c.getPC());if(depth_&&waiting(jobs_[depth_-1])&&at==jobs_[depth_-1].returned){auto&j=jobs_[depth_-1];std::visit([&](auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,T>)t.resumeChild(t.child()==T::Child::Voice?uint32_t(c.reg32(3)):t.child()==T::Child::Read?(uint32_t(uint16_t(c.reg16(4)))<<8)|uint8_t(c.reg8(8)):0);else t.resumeChild((uint32_t(uint16_t(c.reg16(4)))<<8)|uint8_t(c.reg8(8)));},j.task);}
 if(!depth_||at!=boundary(jobs_[depth_-1])){Job j;if(at==0x819a)j.task.emplace<T>();else if(at==0x834a)j.task.emplace<Q>();else return false;if(depth_==jobs_.size())throw std::logic_error("K voice feedback capacity");jobs_[depth_++]=j;}
 auto&j=jobs_[depth_-1];if(waiting(j))return false;if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(int(at+1));
 if(auto*t=std::get_if<T>(&j.task)){using S=T::Stage;switch(t->stage()){
 case S::Increment:{int old=c.reg8(8),v=old+1;val(c,v);c.ccr=uint8_t((c.ccr&~2)|((~old&v&0x80)?2:0));c.reg8(8)=int8_t(v);break;}case S::CompareCount:arithmetic(c,uint8_t(c.reg8(8)),uint8_t(c.reg8(0)),8,true);break;case S::ClearCursor:arithmetic(c,uint8_t(c.reg8(8)),uint8_t(c.reg8(8)),8,true);c.reg8(8)=0;break;
 case S::LookupVoice:case S::InvalidateInactive:case S::ReadInactive:case S::InvalidateActive:case S::ReadActive:j.returned=at+len;call(c,t->stage()==S::LookupVoice?0x72ba:t->stage()==S::InvalidateInactive||t->stage()==S::InvalidateActive?0x5bb8:0x5bde,j.returned,true);break;
 case S::BindInactive:case S::BindActive:c.reg16(4)=int16_t(t->dspAddress());val(c,c.reg16(4));break;case S::TestInactive:c.ccr=uint8_t((c.ccr&~4)|((uint8_t(c.reg8(8))&1)?0:4));break;case S::SetInactive:c.reg32(6)=0x7fffffff;val(c,c.reg32(6));break;
 case S::ShiftActive:{auto v=uint16_t(c.reg16(4));c.ccr=uint8_t((c.ccr&~1)|(v&1));c.reg16(4)=int16_t(v>>1);val(c,c.reg16(4));break;}case S::MaskState:c.reg16(14)&=0x4000;val(c,c.reg16(14));break;case S::MergeState:c.reg16(14)|=c.reg16(4);val(c,c.reg16(14));break;
 case S::DecrementCounter:{int old=c.reg16(6),v=old-1;val(c,v);c.ccr=uint8_t((c.ccr&~2)|((old&~v&0x8000)?2:0));c.reg16(6)=int16_t(v);break;}case S::Return:ret(c);break;default:break;}
 t->advanceBefore(cost,cr,[&](unsigned field)->uint32_t{if(field<2){auto reg=field?0:8;c.reg8(reg)=c.read8(field?0xd022:0xd0ec);val(c,c.reg8(reg));return uint8_t(c.reg8(reg));}auto reg=field==2?14:6;c.reg16(reg)=int16_t(c.read16(int(t->voice()+(field==2?8:10))));val(c,c.reg16(reg));return uint16_t(c.reg16(reg));},[&](unsigned field,uint32_t v){if(field<2){val(c,c.reg8(8));c.write8(int8_t(v),field?0xd0ec:0xd023);}else if(field==2){c.write32(int32_t(v),int(t->voice()+8));val(c,c.reg32(6));}else{c.write16(int16_t(v),int(t->voice()+(field==3?8:10)));val(c,c.reg16(field==3?14:6));}});
 }else{auto&task=std::get<Q>(j.task);using S=Q::Stage;switch(task.stage()){case S::BindAddress:c.reg16(4)=int16_t(0x802b);val(c,c.reg16(4));break;case S::RetainAddress:c.setSP(c.getSP()-2);c.write16(c.reg16(4),int(c.getSP()));c.clockI(2);val(c,c.reg16(4));break;case S::Read:case S::Write:case S::Global:j.returned=at+len;call(c,task.stage()==S::Read?0x16fa:task.stage()==S::Write?0x165e:0x79a4,j.returned,true);break;case S::RestoreAddress:c.reg16(4)=int16_t(c.read16(int(c.getSP())));c.setSP(c.getSP()+2);c.clockI(2);val(c,c.reg16(4));break;case S::Compare:arithmetic(c,uint8_t(c.reg8(8)),3,8,true);break;case S::Clear:arithmetic(c,uint32_t(c.reg32(1)),uint32_t(c.reg32(1)),32,true);c.reg32(1)=0;break;case S::Return:ret(c);break;default:break;}task.advanceBefore(cost,cr);}
 if(c.cycles-begin!=cost)throw std::logic_error("K voice feedback clocks");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(int(boundary(j)));return true;
 }
private:
 static bool waiting(const Job&j){return std::visit([](const auto&t){return t.awaitingChild();},j.task);}
 static uint32_t boundary(const Job&j){if(waiting(j))return j.returned;return std::visit([](const auto&t)->uint32_t{using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,T>){constexpr uint32_t p[]{0x819a,0x81a0,0x81a6,0x81a8,0x81ae,0x81b0,0x81b2,0x81b4,0x81ba,0x81be,0x81c6,0x81c8,0x81ca,0x81ce,0x81d2,0x81d6,0x81d8,0x81da,0x81e0,0x81ea,0x81ec,0x81f0,0x81f4,0x81f8,0x81fa,0x81fe,0x8200,0x8208,0x820a,0x820e,0x8210,0x8212,0x8216,0};return p[unsigned(t.stage())];}else{constexpr uint32_t p[]{0x834a,0x834e,0x8350,0x8354,0x8356,0x8358,0x835a,0x835c,0x8360,0x8364,0};return p[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){return std::visit([](const auto&t){using J=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<J,T>){using S=T::Stage;switch(t.stage()){case S::ReadCursor:case S::PublishVoice:case S::ReadCount:case S::PublishCursor:case S::SetInactive:return 6u;case S::ReadState:case S::PublishState:return 8u;case S::PublishInactive:return 10u;case S::LookupVoice:case S::InvalidateInactive:case S::BindInactive:case S::ReadInactive:case S::InvalidateActive:case S::BindActive:case S::ReadActive:case S::MaskState:case S::ReadCounter:case S::PublishCounter:return 4u;default:return 2u;}}else return t.stage()==Q::Stage::BindAddress||t.stage()==Q::Stage::Read||t.stage()==Q::Stage::Write||t.stage()==Q::Stage::Global?4u:2u;},j.task);}
 static unsigned bus(uint32_t a,unsigned bytes,int last){unsigned n=0;for(unsigned i=0;i<bytes;++i){auto at=(a+i)&0xffffff;if(at<0x400000||(at>=0xfffd10&&at<0xffffa0)){if((last&1)||at!=uint32_t(last|1))n+=at<0x400000?3:1;last=int(at);}else{n+=at>=0xffffa0?1:3;last=-1;}}return n;}
 static VoiceFeedbackCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){VoiceFeedbackCredits cr;auto r=int(c.getPC()+len-1);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,r);cr.retain=5+bus(c.getSP()-2,2,c.writeHistory());cr.restore=5+bus(c.getSP(),2,r);if(auto*t=std::get_if<T>(&j.task)){cr.readState=12+bus(t->voice()+8,2,r);cr.writeState=12+bus(t->voice()+8,2,c.writeHistory());cr.writeInactive=15+bus(t->voice()+8,4,c.writeHistory());cr.readCounter=6+bus(t->voice()+10,2,r);cr.writeCounter=6+bus(t->voice()+10,2,c.writeHistory());}return cr;}
 std::array<Job,4>jobs_{};unsigned depth_=0;
};
}
